67	        if (uriA == null || uriB == null) {
68	            return uriA == uriB;
69	        }
70	        String schemeA = uriA.getScheme();
71	        String schemeB = uriB.getScheme();
72	        if (schemeA == null || schemeB == null || !schemeA.equalsIgnoreCase(schemeB)) {
73	            return false;
74	        }
75	        return hostsEqual(uriA, uriB);
76	    }
