96	        String userInfoA = uriA.getRawUserInfo();
97	        String userInfoB = uriB.getRawUserInfo();
98	        if (userInfoA != null || userInfoB != null) {
99	            return Objects.equals(userInfoA, userInfoB);
100	        }
101	        return Objects.equals(userInfoFromAuthority(uriA.getRawAuthority()),
102	                userInfoFromAuthority(uriB.getRawAuthority()));
