104	
105	    /**
106	     * Whether the URI authority includes an explicit port separator (including an empty port).
107	     * Used for port-wildcard redirect prefixes such as {@code https://example.com:*}.
108	     * IPv6 literals are handled so colons inside {@code [...]} are not treated as a port.
109	     */
