120	    /**
121	     * Whether the URI authority is safe for wildcard redirect matching.
122	     * <p>
123	     * Allows hosts Java parses normally and RFC 3986 registry-names (e.g. underscores)
124	     * that leave {@link URI#getHost()} null, while rejecting authorities with user-info
125	     * or invalid ports. See CVE-2026-7504.
126	     */
127	    public static boolean isAuthoritySafeForWildcards(URI uri) {
128	        if (uri == null) {
129	            return false;
130	        }
131	        String authority = uri.getRawAuthority();
132	        if (uri.getRawUserInfo() != null || (authority != null && authority.indexOf('@') >= 0)) {
133	            return false;
134	        }
135	        if (authority == null || uri.getHost() != null) {
136	            return true;
137	        }
138	        // Registry-name host (getHost() null): require a resolvable host and a valid port if present
139	        String host = resolveHost(uri);
