152	        }
153	    }
154	
155	    private static boolean hostsEqual(URI uriA, URI uriB) {
156	        String hostA = resolveHost(uriA);
157	        String hostB = resolveHost(uriB);
158	        if (hostA != null && hostB != null) {
159	            // ASCII-only: String.equalsIgnoreCase also folds Unicode (e.g. ı ↔ i).
160	            return asciiEqualsIgnoreCase(hostA, hostB);
161	        }
162	        if (hostA != null || hostB != null) {
163	            return false;
164	        }
