170	        return false;
171	    }
172	
173	    /**
174	     * Case-insensitive equality restricted to ASCII {@code A-Z}/{@code a-z}.
175	     * Unlike {@link String#equalsIgnoreCase(String)}, this does not fold Unicode
176	     * letters (e.g. Latin small letter dotless i {@code ı} must not match {@code i}).
