178	    private static boolean asciiEqualsIgnoreCase(String a, String b) {
179	        int len = a.length();
180	        if (len != b.length()) {
181	            return false;
182	        }
183	        for (int i = 0; i < len; i++) {
184	            char ca = a.charAt(i);
185	            char cb = b.charAt(i);
186	            if (ca == cb) {
187	                continue;
188	            }
189	            if (ca >= 'A' && ca <= 'Z') {
190	                ca += 'a' - 'A';
191	            }
192	            if (cb >= 'A' && cb <= 'Z') {
193	                cb += 'a' - 'A';
194	            }
195	            if (ca != cb) {
196	                return false;
197	            }
198	        }
199	        return true;
200	    }
