208	     * user-info or port separators (e.g. {@code evil%40good.com} stays one host).
209	     */
210	    private static String resolveHost(URI uri) {
211	        String host = uri.getHost();
212	        if (host != null) {
213	            return host;
214	        }
215	        String authority = uri.getRawAuthority();
216	        if (authority == null) {
217	            return null;
218	        }
219	        return hostFromHostPort(hostPortFromAuthority(authority));
220	    }
