233	    }
234	
235	    private static String userInfoFromAuthority(String authority) {
236	        if (authority == null) {
237	            return null;
238	        }
239	        int at = authority.lastIndexOf('@');
240	        return at >= 0 ? authority.substring(0, at) : null;
241	    }
242	
243	    private static String hostPortFromAuthority(String authority) {
244	        if (authority == null) {
245	            return null;
246	        }
247	        int at = authority.lastIndexOf('@');
248	        return at >= 0 ? authority.substring(at + 1) : authority;
249	    }
250	
251	    private static String hostFromHostPort(String hostPort) {
252	        if (hostPort == null) {
253	            return "";
254	        }
255	        if (hostPort.startsWith("[")) {
256	            int close = hostPort.indexOf(']');
257	            return close >= 0 ? hostPort.substring(0, close + 1) : hostPort;
258	        }
259	        int colon = hostPort.lastIndexOf(':');
260	        return colon >= 0 ? hostPort.substring(0, colon) : hostPort;
261	    }
