265	     * An empty string means an explicit empty port (authority ends with {@code :}).
266	     * For IPv6, only a colon after the closing {@code ]} counts as a port separator.
267	     */
268	    private static String portSuffixFromAuthority(String authority) {
269	        String hostPort = hostPortFromAuthority(authority);
270	        if (hostPort == null) {
271	            return null;
272	        }
273	        if (hostPort.startsWith("[")) {
274	            int close = hostPort.indexOf(']');
275	            if (close < 0 || close + 1 >= hostPort.length() || hostPort.charAt(close + 1) != ':') {
276	                return null;
277	            }
278	            return hostPort.substring(close + 2);
279	        }
280	        int colon = hostPort.lastIndexOf(':');
281	        if (colon < 0) {
282	            return null;
283	        }
284	        return hostPort.substring(colon + 1);
285	    }
286	
287	    public static String getHost(String uri) {
288	        try {
289	            if (uri == null) return null;
290	            URI url = new URI(uri);
291	            return url.getHost();
292	        } catch (URISyntaxException uriSyntaxException) {
293	            throw new IllegalArgumentException("URI '" + uri + "' is not valid.");
294	        }
295	    }
