297	    public static MultivaluedHashMap<String, String> parseQueryParameters(String queryString, boolean decode) {
298	        MultivaluedHashMap<String, String> map = new MultivaluedHashMap<String, String>();
299	        if (queryString == null || queryString.equals("")) return map;
300	
301	        String[] params = queryString.split("&");
302	
303	        for (String param : params)
304	        {
305	            if (param.indexOf('=') >= 0)
306	            {
307	                String[] nv = param.split("=", 2);
308	                try
309	                {
310	                    String name = decode ? URLDecoder.decode(nv[0], "UTF-8") : nv[0];
311	                    String val = nv.length > 1 ? nv[1] : "";
312	                    map.add(name, decode ? URLDecoder.decode(val, "UTF-8") : val);
313	                }
314	                catch (UnsupportedEncodingException e)
315	                {
316	                    throw new RuntimeException(e);
317	                }
318	            }
319	            else
320	            {
321	                try
322	                {
323	                    String name = decode ? URLDecoder.decode(param, "UTF-8") : param;
324	                    map.add(name, "");
325	                }
326	                catch (UnsupportedEncodingException e)
327	                {
328	                    throw new RuntimeException(e);
329	                }
330	            }
331	        }
332	        return map;
333	    }
334	
335	    public static MultivaluedHashMap<String, String> decodeQueryString(String queryString) {
336	        return parseQueryParameters(queryString, true);
337	    }
338	
339	    public static String stripQueryParam(String url, String name){
340	        return url.replaceFirst("[\\?&]"+name+"=[^&]*$|"+name+"=[^&]*&", "");
341	    }
342	
343	    public static void checkUrl(SslRequired sslRequired, String url, String name) throws IllegalArgumentException{
344	        if (url == null) {
345	            return;
346	        }
347	
348	        URL parsed;
349	
350	        try {
351	            parsed = new URL(url);
352	        } catch (MalformedURLException e) {
353	            throw new IllegalArgumentException("The url [" + name + "] is malformed", e);
354	        }
355	
356	        String protocol = parsed.getProtocol().toLowerCase();
357	
358	        if (!("http".equals(protocol) || "https".equals(protocol))) {
359	            throw new IllegalArgumentException("Invalid protocol/scheme for url [" + name + "]");
360	        }
361	
362	        if (!"https".equals(protocol) && sslRequired.isRequired(parsed.getHost())) {
363	            throw new IllegalArgumentException("The url [" + name + "] requires secure connections");
364	        }
365	    }
366	}
