        }
    }

    private static boolean hostsEqual(URI uriA, URI uriB) {
        String hostA = resolveHost(uriA);
        String hostB = resolveHost(uriB);
        if (hostA != null && hostB != null) {
            // ASCII-only: String.equalsIgnoreCase also folds Unicode (e.g. ı ↔ i).
